import java.io.*;
import java.util.*;

public class Main {
    static class Edge {
        int src, dst;
        int cap;
        long cost;
        int rev;
        Edge(int s, int d, int c, long co, int r) {
            src = s; dst = d; cap = c; cost = co; rev = r;
        }
    }

    static class FlowBase {
        int n;
        ArrayList<ArrayList<Integer>> adj;
        ArrayList<Edge> edges;

        FlowBase(int n) {
            this.n = n;
            adj = new ArrayList<>(n);
            for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
            edges = new ArrayList<>();
        }

        int size() { return n; }

        void addEdge(int src, int dst, int cap, long cost) {
            if (cap <= 0) return;
            int fwd = edges.size();
            edges.add(new Edge(src, dst, cap, cost, fwd + 1));
            edges.add(new Edge(dst, src, 0, -cost, fwd));
            adj.get(src).add(fwd);
            adj.get(dst).add(fwd + 1);
        }
    }

    static class MinCostFlow extends FlowBase {
        long minCost, totalCost;
        int[] supp;
        long[] ptnl, dist;
        int[] last;

        MinCostFlow(int n) {
            super(n + 2);
            minCost = 0;
            totalCost = 0;
            supp = new int[n + 2];
            ptnl = new long[n + 2];
            dist = new long[n + 2];
            last = new int[n + 2];
        }

        int size() { return n - 2; }

        void addEdge(int src, int dst, int cap, long cost) {
            if (cap <= 0) return;
            if (cost < 0) {
                supp[src] -= cap;
                supp[dst] += cap;
                minCost += cap * cost;
                totalCost -= cap * cost;
                super.addEdge(dst, src, cap, -cost);
            } else {
                totalCost += cap * cost;
                super.addEdge(src, dst, cap, cost);
            }
        }

        void supply(int node, int vol) {
            supp[node] += vol;
        }

        boolean dijkstra(int src, int dst) {
            long infty = totalCost + 1;
            Arrays.fill(dist, infty);
            dist[src] = 0;
            PriorityQueue<long[]> pq = new PriorityQueue<>(Comparator.comparingLong(a -> a[0]));
            pq.offer(new long[]{0, src});
            while (!pq.isEmpty()) {
                long[] cur = pq.poll();
                long ndist = cur[0];
                int now = (int) cur[1];
                if (ndist != dist[now]) continue;
                ptnl[now] += ndist;
                dist[now] = -1; // mark invalid
                for (int eid : adj.get(now)) {
                    Edge e = edges.get(eid);
                    if (dist[e.dst] == -1 || e.cap == 0) continue;
                    long newDist = ptnl[now] + e.cost - ptnl[e.dst];
                    if (dist[e.dst] > newDist) {
                        dist[e.dst] = newDist;
                        last[e.dst] = eid;
                        pq.offer(new long[]{newDist, e.dst});
                    }
                }
            }
            return dist[dst] == -1; // true if unreachable
        }

        boolean solve() {
            int src = n - 2;
            int dst = src + 1;
            int flow = 0;
            int suppSum = 0;
            for (int i = 0; i < n; i++) {
                suppSum += supp[i];
                if (supp[i] > 0) {
                    flow += supp[i];
                    addEdge(src, i, supp[i], 0);
                } else if (supp[i] < 0) {
                    addEdge(i, dst, -supp[i], 0);
                }
                supp[i] = 0;
            }
            if (suppSum != 0) return false;
            while (flow > 0) {
                if (dijkstra(src, dst)) return false;
                int resid = flow;
                for (int node = dst; node != src; node = edges.get(last[node]).src) {
                    resid = Math.min(resid, edges.get(last[node]).cap);
                }
                flow -= resid;
                minCost += ptnl[dst] * resid;
                for (int node = dst; node != src; node = edges.get(last[node]).src) {
                    Edge e = edges.get(last[node]);
                    e.cap -= resid;
                    edges.get(e.rev).cap += resid;
                }
            }
            return true;
        }

        long optimal() {
            solve();
            return minCost;
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());
        int k = Integer.parseInt(st.nextToken());
        int c = Integer.parseInt(st.nextToken());
        int d = Integer.parseInt(st.nextToken());
        final int tlim = 105;
        MinCostFlow mcf = new MinCostFlow(6100);
        st = new StringTokenizer(br.readLine());
        for (int i = 0; i < k; i++) {
            int j = Integer.parseInt(st.nextToken()) - 1;
            mcf.supply(j, 1);
        }
        for (int i = 0; i < m; i++) {
            st = new StringTokenizer(br.readLine());
            int u = Integer.parseInt(st.nextToken()) - 1;
            int v = Integer.parseInt(st.nextToken()) - 1;
            for (int t = 0; t < tlim; t++) {
                int nu = u + n;
                int nv = v + n;
                for (int x = 0; x < k; x++) {
                    mcf.addEdge(u, nv, 1, c + d * (2L * x + 1));
                    mcf.addEdge(v, nu, 1, c + d * (2L * x + 1));
                }
                u = nu;
                v = nv;
            }
        }
        for (int i = 1; i < n; i++) {
            for (int t = 0; t < tlim; t++) {
                mcf.addEdge(n * t + i, n * (t + 1) + i, k, c);
            }
        }
        int dst = mcf.size() - 1;
        mcf.supply(dst, -k);
        for (int t = 0; t <= tlim; t++) {
            mcf.addEdge(t * n, dst, k, 0);
        }
        System.out.println(mcf.optimal());
    }
}
